#!/usr/bin/env node
/**
 * Verify the skills published in @proofable/sdk match the canonical public
 * skills in proofable/mcp (skills/ there is the single source of truth; the
 * copies here are generated by that repo's scripts/sync-plugin-skills.mjs).
 *
 * The two live in different repositories, so they can only agree once both
 * carry the same content. While the paired pull requests are open, the sibling
 * is on its default branch and a mismatch is expected — not a defect here.
 *
 *   node scripts/check-mcp-skill-parity.mjs            informational (exit 0)
 *   node scripts/check-mcp-skill-parity.mjs --require  gate: exit 1 on mismatch
 *
 * Default is informational so pull-request CI never blocks on an unlandable
 * cross-repository comparison. Release runs with --require, where both sides are
 * settled. CI sets PROOFABLE_MCP_SKILLS_ROOT to the checked-out proofable/mcp.
 */
import { createHash } from 'node:crypto';
import { readdirSync, readFileSync, existsSync } from 'node:fs';
import path from 'node:path';
import process from 'node:process';

const requireMatch = process.argv.includes('--require');
const sdkRoot = process.cwd();
const mcpSkillsRoot = process.env.PROOFABLE_MCP_SKILLS_ROOT
  ? path.resolve(process.env.PROOFABLE_MCP_SKILLS_ROOT)
  : path.resolve(sdkRoot, '../mcp/skills');

function directoryDigest(dir) {
  const entries = [];
  const visit = (current) => {
    for (const entry of readdirSync(current, { withFileTypes: true })) {
      const fullPath = path.join(current, entry.name);
      if (entry.isDirectory()) {
        visit(fullPath);
      } else if (entry.isFile()) {
        // Normalize line endings so a checkout's autocrlf setting cannot
        // create false parity failures against the canonical copies.
        const text = readFileSync(fullPath, 'utf8').replaceAll('\r\n', '\n');
        entries.push(`${path.relative(dir, fullPath).replaceAll(path.sep, '/')}\0${text}`);
      }
    }
  };
  visit(dir);
  entries.sort();
  return createHash('sha256').update(entries.join('\0')).digest('hex');
}

function listSkills(root) {
  if (!existsSync(root)) return null;
  return readdirSync(root, { withFileTypes: true })
    .filter((entry) => entry.isDirectory())
    .filter((entry) => existsSync(path.join(root, entry.name, 'SKILL.md')))
    .map((entry) => entry.name)
    .sort();
}

const mcpSkills = listSkills(mcpSkillsRoot);
if (!mcpSkills) {
  console.error(`skill parity: canonical skills directory not found: ${mcpSkillsRoot}`);
  console.error('Set PROOFABLE_MCP_SKILLS_ROOT or clone proofable/mcp as a sibling.');
  process.exit(1);
}

const sdkSkills = listSkills(path.join(sdkRoot, 'skills')) ?? [];
const errors = [];

for (const name of mcpSkills) {
  if (!sdkSkills.includes(name)) {
    errors.push(`skills/${name} is missing here; run sync in proofable/mcp`);
    continue;
  }
  const mcpDigest = directoryDigest(path.join(mcpSkillsRoot, name));
  const sdkDigest = directoryDigest(path.join(sdkRoot, 'skills', name));
  if (mcpDigest !== sdkDigest) {
    errors.push(`skills/${name} differs from proofable/mcp; run sync in proofable/mcp`);
  }
}

for (const name of sdkSkills) {
  if (!mcpSkills.includes(name)) {
    errors.push(`skills/${name} exists here but not in proofable/mcp canonical skills/`);
  }
}

if (errors.length > 0) {
  if (!requireMatch) {
    console.warn('skill parity: not yet aligned with proofable/mcp (informational):');
    for (const error of errors) console.warn(`  - ${error}`);
    console.warn(
      'Expected while the paired pull requests are open. Release enforces this with --require.',
    );
    process.exit(0);
  }
  console.error('skill parity: out of sync with proofable/mcp:');
  for (const error of errors) console.error(`  - ${error}`);
  process.exit(1);
}

console.log(`skill parity: all ${mcpSkills.length} skills match proofable/mcp canonical skills/.`);